html:
{%- 
    set is_rescheduled = doc.is_rescheduled == 1 or doc.entrance_test_status == "Rescheduled"
-%}

{%- if is_rescheduled -%}
    {%- set f_date = doc.re_allocation_date -%}
    {%- set f_test = doc.re_entrance_test_name or doc.re_entrance_test_list -%}
    {%- set f_seat = doc.re_seat_number -%}
    {%- set f_room = doc.re_room_name -%}
    {%- set f_code = doc.re_room_code -%}
    {%- set f_building = doc.re_building -%}
    {%- set f_floor = doc.re_floor -%}
    {%- set f_center = doc.re_center_name -%}
    {%- set f_address = doc.re_center_address -%}
    {%- set f_status = doc.re_allocation_status -%}
{%- else -%}
    {%- set f_date = doc.allocation_date -%}
    {%- set f_test = doc.entrance_test_name or doc.entrance_test_list -%}
    {%- set f_seat = doc.seat_number -%}
    {%- set f_room = doc.room_name -%}
    {%- set f_code = doc.room_code -%}
    {%- set f_building = doc.building -%}
    {%- set f_floor = doc.floor -%}
    {%- set f_center = doc.center_name -%}
    {%- set f_address = doc.center_address -%}
    {%- set f_status = doc.allocation_status -%}
{%- endif -%}

{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set admit_no = doc.admit_card_number or ("AC-" + doc.name) -%}
{%- set dob = frappe.utils.formatdate(doc.date_of_birth) if doc.date_of_birth else "—" -%}
{%- set exam_date_time = (frappe.utils.format_datetime(f_date, "dd-MM-yyyy hh:mm a") if f_date else "—") -%}
{%- set centre_full = "<strong>" + (f_center or "—") + "</strong><br><span style='font-size:10px; color:#444;'>" + (f_address or "—") + "</span>" -%}

{%- set _site = frappe.utils.get_url() -%}

{#- PRODUCTION IMAGE HANDLER -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}{%- set _logo_src = _site ~ campus_logo_path -%}{%- endif -%}
{%- endif -%}

{%- set _photo_src = '' -%}
{%- if doc.profile -%}
    {%- set _pb64 = get_file_b64(doc.profile) -%}
    {%- if _pb64 -%}
        {%- set _pext = (doc.profile.split('.')[-1] | lower) -%}
        {%- set _pmime = 'image/jpeg' if _pext in ['jpg','jpeg'] else ('image/png' if _pext == 'png' else 'image/webp') -%}
        {%- set _photo_src = 'data:' ~ _pmime ~ ';base64,' ~ _pb64 -%}
    {%- else -%}{%- set _photo_src = _site ~ doc.profile -%}{%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html>
<head>
<link href="https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;1,300;1,400;1,700&display=swap" rel="stylesheet">
<meta charset="UTF-8"/>
<style>
    @page { size: A4; margin: 10mm; }
    html, body { margin: 0 !important; padding: 0 !important; background: #fff !important; }
    body { font-family: 'Merriweather', serif; font-size: 11px; color: #000; line-height: 1.3; }

    .card-page { width: 100%; border: 1.5px solid #444; background: #fff; page-break-after: always; overflow: hidden; }
    .card-page:last-child { page-break-after: auto; }

    table { width: 100%; border-collapse: collapse; table-layout: fixed; }
    td { vertical-align: top; padding: 0; }

    /* Header */
    .hdr-bg { background: #7b1c1c !important; color: #ffffff !important; border-bottom: 3px solid #5a0e0e; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .univ-name { font-size: 17px; font-weight: bold; text-transform: uppercase; color: #ffffff !important; }
    .univ-sub { font-size: 9px; color: #ffffff !important; opacity: 0.85; letter-spacing: 1px; }

    /* Title */
    .title-strip { border-bottom: 1.5px solid #bbb; text-align: center; padding: 6px 0; background: #fdfdfd !important; }
    .t1 { font-size: 13px; font-weight: bold; }
    .t2 { font-size: 10px; color: #444; margin-top: 2px; }

    /* Data Table */
    .main-body { padding: 10px; }
    .inner-border { border: 1.2px solid #888; }
    .data-tbl td { padding: 5px 8px; border-bottom: 1px solid #eee; font-size: 11px; }
    .data-tbl td.lb { font-weight: bold; width: 35%; background: #f8f8f8 !important; color: #222; }
    .data-tbl td.vl { width: 65%; color: #000; }

    /* Photo */
    .photo-col { border-left: 1.2px solid #888; text-align: center; padding: 8px; vertical-align: top; background: #fafafa !important; }
    .photo-box { width: 110px; height: 135px; border: 1px solid #444; background: #eee; margin: 0 auto 5px; }
    .photo-label { font-size: 9px; font-style: italic; color: #666; }

    /* Sig Section */
    .sig-area { padding: 0 10px 10px; page-break-inside: avoid; }
    .sig-note { text-align: center; font-style: italic; font-size: 10px; margin-bottom: 6px; }
    .sig-box-tbl td { border: 1.2px solid #888; width: 50%; height: 60px; }
    .sig-label { background: #f0f0f0 !important; font-weight: bold; padding: 4px; text-align: center; border-bottom: 1.2px solid #888; font-size: 10px; display: block; }

    /* Instructions Section */
    .inst-padding { padding: 15px 18px; }
    .inst-header { font-size: 14px; font-weight: bold; text-align: center; color: #7b1c1c; border-bottom: 2px solid #7b1c1c; padding-bottom: 5px; margin-bottom: 10px; }
    .sec-head { font-size: 11px; font-weight: bold; color: #000; margin-top: 8px; margin-bottom: 3px; }

    .list-tbl td { padding: 2px 0; font-size: 10.5px; line-height: 1.35; vertical-align: top; }
    .list-tbl .mk { width: 20px; font-weight: bold; }
    .list-tbl .sub-mk { width: 25px; font-style: italic; padding-left: 15px; }

    .footer-tbl { border-top: 1px solid #eee; padding: 6px 10px; font-size: 8px; color: #888; }
</style>
</head>
<body>

<!-- PAGE 1: ADMIT CARD -->
<div class="card-page">
    <table class="hdr-bg">
        <tr>
            <td style="width: 80px; padding: 8px 12px;">
                <div style="background:#fff; width:55px; height:55px; border-radius:3px; overflow:hidden;">
                    {% if _logo_src %}<img src="{{ _logo_src }}" style="width:100%; height:100%; object-fit:contain;">
                    {% else %}<div style="color:#7b1c1c; font-weight:bold; text-align:center; line-height:55px; font-size:9px;">LOGO</div>{% endif %}
                </div>
            </td>
            <td style="padding: 8px 0; text-align: center; vertical-align: middle;">
                <div class="univ-name">{{ campus_display_name }}</div>
                <div class="univ-sub">OFFICE OF ADMISSIONS &middot; EXAMINATION CELL</div>
            </td>
            <td style="width: 80px;"></td>
        </tr>
    </table>

    <div class="title-strip">
        <div class="t1">Admit Card ({{ f_test or "—" }})</div>
        <div class="t2">Admission to {{ doc.program_level or "the Programme" }} | {{ doc.academic_year or "—" }} | {{ doc.admission_cycle or "—" }}</div>
    </div>

    <div class="main-body">
        <table class="inner-border">
            <tr>
                <td style="width: 75%;">
                    <table class="data-tbl">
                        <tr><td class="lb">Admit Card Number</td><td class="vl"><strong>{{ admit_no }}</strong></td></tr>
                        <tr><td class="lb">Candidate's Name</td><td class="vl">{{ doc.candidate_name or "—" }}</td></tr>
                        <tr><td class="lb">Date of Birth</td><td class="vl">{{ dob }}</td></tr>
                        <tr><td class="lb">Father's Name</td><td class="vl">{{ doc.father_name or "—" }}</td></tr>
                        <tr><td class="lb">Mother's Name</td><td class="vl">{{ doc.mother_name or "—" }}</td></tr>
                        <tr><td class="lb">Gender</td><td class="vl">{{ doc.gender or "—" }}</td></tr>
                        <tr><td class="lb">Programme Applied</td><td class="vl">{{ doc.program or "—" }}</td></tr>
                        <tr><td class="lb">Application Number</td><td class="vl">{{ doc.applicant or "—" }}</td></tr>
                        <tr><td class="lb">Examination Date & Time</td><td class="vl">{{ exam_date_time|safe }}</td></tr>
                        <tr><td class="lb">Test Center</td><td class="vl">{{ f_center or "—" }}</td></tr>
                        <tr><td class="lb">Reporting Time</td><td class="vl">30 minutes before scheduled time</td></tr>
                        <tr><td class="lb">Seat Number</td><td class="vl">{{ f_seat or "—" }}</td></tr>
                        <tr><td class="lb">Room No/Room Code</td><td class="vl">{{ f_room or "—" }}/{{ f_code or "—" }}</td></tr>
                        <tr><td class="lb">Building / Floor</td><td class="vl">{{ f_building or "—" }}{% if f_floor %} &middot; Floor: {{ f_floor }}{% endif %}</td></tr>
                        <tr><td class="lb">Allocation Status</td><td class="vl"><span style="border:1px solid #4caf50; color:#1b5e20; background:#f0fdf0 !important; font-size:9.5px; font-weight:bold; padding:0 8px; border-radius:10px;">{{ f_status or "—" }}</span></td></tr>
                        <tr><td class="lb" style="border-bottom:none;">Test Centre Address</td><td class="vl" style="border-bottom:none; font-size:9.5px;">{{ centre_full|safe }}</td></tr>
                    </table>
                </td>
                <td class="photo-col" style="width: 25%;">
                    <div class="photo-box">
                        {% if _photo_src %}<img src="{{ _photo_src }}" style="width:100%; height:100%; object-fit:cover;">
                        {% else %}<div style="line-height:135px; font-size:40px; color:#ccc;">👤</div>{% endif %}
                    </div>
                    <div class="photo-label">Candidate's Photograph</div>

                    <div style="height: 45px; border-bottom: 1.2px solid #888; margin: 12px 10px 0;"></div>
                    <div class="photo-label" style="margin-top:4px;">Signature at Reporting</div>
                </td>
            </tr>
        </table>
    </div>

    <div class="sig-area">
        <div class="sig-note">To be signed in the presence of the Invigilator in the Examination Hall</div>
        <table class="sig-box-tbl">
            <tr>
                <td><span class="sig-label">Candidate's Signature</span></td>
                <td><span class="sig-label">Invigilator's Signature</span></td>
            </tr>
        </table>
    </div>

    <table class="footer-tbl">
        <tr>
            <td style="text-align: left;">Doc ID: {{ doc.name }} | Generated: {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</td>
            <td style="text-align: right;"></td>
        </tr>
    </table>
</div>

<!-- PAGE 2: INSTRUCTIONS -->
<div class="card-page">
    <div class="inst-padding">
        <div class="inst-header">Instructions to Candidates</div>

        <div class="sec-head">1. General Instructions</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates should check and review their admit cards carefully and make sure that their Name, Date of Birth, and other personal details mentioned in the admit card are as per the details filled by them in the application form. In case of any discrepancy, please contact the Examination Cell immediately.</td></tr>
            <tr><td class="mk">b.</td><td>Please carry a printed copy of this admit card to the test centre.</td></tr>
        </table>

        <div class="sec-head">2. Reporting to the Test Centre & Test Timings</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates will be allowed to enter the premises of the test centre 30 minutes before the examination start time and should be seated in the examination hall at least 15 minutes before commencement.</td></tr>
            <tr><td class="mk">b.</td><td>Candidates should carry a Government-issued photo ID card, preferably the one uploaded with the application form. The ID card will be checked at the time of entry into the centre.</td></tr>
            <tr><td class="mk">c.</td><td>Candidates who arrive at the test centre beyond the scheduled entry cut-off time will not be permitted entry.</td></tr>
            <tr><td class="mk">d.</td><td>Once the test commences, Candidates will not be permitted to leave the examination hall until the test is completed, and all the Question Booklets and OMR response sheets have been collected by the invigilator/s.</td></tr>
        </table>

        <div class="sec-head">3. Pre-Test Instructions</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates shall be required to follow all directions issued by the Centre Coordinators and the Institution representatives at their respective test centres.</td></tr>
            <tr><td class="mk">b.</td><td>Candidates must maintain all protocols in place at their respective test centres.</td></tr>
        </table>

        <div class="sec-head">4. Permitted Items</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates will only be permitted to carry the following inside the Test Centre:</td></tr>
        </table>
        <table class="list-tbl">
            <tr><td class="sub-mk">i.</td><td>Admit Card (In case the photograph on the Admit Card is not clear, candidates should carry a self-attested passport size photograph).</td></tr>
            <tr><td class="sub-mk">ii.</td><td>Government Issued Photo ID (preferably the one uploaded with the application form).</td></tr>
            <tr><td class="sub-mk">iii.</td><td>Black or Blue Ballpoint pen.</td></tr>
            <tr><td class="sub-mk">iv.</td><td>A transparent water bottle.</td></tr>
            <tr><td class="sub-mk">v.</td><td>A face mask (the Candidate may be asked to remove the face mask for ascertainment of identity).</td></tr>
            <tr><td class="sub-mk">vi.</td><td>An analogue watch. <strong>Note:</strong> Smart Watches are not permitted.</td></tr>
        </table>

        <div class="sec-head">5. Admissions Test Related Instructions</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>An attendance sheet will be circulated during the admissions test. The requisite details should be filled in the attendance sheet.</td></tr>
            <tr><td class="mk">b.</td><td>Candidates will be provided with a Question Booklet and/or answer sheets. Candidates should use black/blue ball point pen <strong>only</strong> to enter the admit card number and other required details.</td></tr>
            <tr><td class="mk">c.</td><td>Candidates must read the instructions provided with the Question Booklet before commencing the test.</td></tr>
            <tr><td class="mk">d.</td><td>Candidates should write the details required on the cover page of the Question Booklet.</td></tr>
            <tr><td class="mk">e.</td><td>No clarifications can be sought about the Question Booklet from anyone.</td></tr>
            <tr><td class="mk">f.</td><td>Candidates shall not carry the Question Booklet out of the examination hall under any circumstances.</td></tr>
        </table>

        <div class="sec-head">6. Documents to be retained by the Candidate after the test</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The admit card, with the invigilator's signature, should be retained by the candidate and produced at the Institution at the time of admission.</td></tr>
        </table>

        <div class="sec-head">7. Malpractice</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The use of any unfair means by a Candidate shall result in their disqualification and cancellation of their test.</td></tr>
            <tr><td class="mk">b.</td><td>Impersonation is an offence, and the Candidate, apart from being disqualified, shall be liable to penal action under the law.</td></tr>
            <tr><td class="mk">c.</td><td>Possession of electronic devices, including mobile phones, headphones, earphones, smart watches, calculators etc., is strictly prohibited in the examination hall.</td></tr>
        </table>
    </div>

    <table class="footer-tbl">
        <tr>
            <td style="text-align: left;">Application: {{ doc.applicant or "—" }}</td>
            <td style="text-align: center; width: 60%;">********************</td>
            <td style="text-align: right;"></td>
        </tr>
    </table>
</div>

</body>
</html>
